for y in range(0,1008,50):
    d.line([(0,y),(1738,y)], fill=(255,0,0) if y%200==0 else (200,200,255), width=1)
    if y%200==0: d.text((2,y+2), str(y), fill=(255,0,0))
im.save('grid.png')
"
